{"path":"/tmp/sctest.c","content":"#define _GNU_SOURCE
#include <stdio.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>
#include <sys/syscall.h>
#include <sys/ptrace.h>
#include <sys/uio.h>

static void probe(const char *name, long ret) {
    if (ret == -1)
        printf("%-18s -> errno=%d (%s)%s\n", name, errno, strerror(errno),
               errno == EPERM ? "  [BLOCKED by seccomp]" : "");
    else
        printf("%-18s -> ret=%ld (allowed)\n", name, ret);
}

int main(void) {
    probe("keyctl",       syscall(SYS_keyctl, 0, 0, 0, 0, 0));
    probe("add_key",      syscall(SYS_add_key, "user", "t", "x", 1, -2));
    probe("request_key",  syscall(SYS_request_key, "user", "t", "", 0));
    probe("ptrace",       syscall(SYS_ptrace, PTRACE_TRACEME, 0, 0, 0));
    int fd[2]; pipe(fd);
    char b[4] = "abcd"; struct iovec l = {b, 4}, r = {b, 4};
    probe("process_vm_writev", syscall(SYS_process_vm_writev, getpid(), &l, 1, &r, 1, 0));
    /* control: a syscall the profile must still allow */
    probe("getpid(allow)", syscall(SYS_getpid));
    return 0;
}
"}
